const emptyState=()=>({company:'Workspace Anda',website:'',products:[],productId:'',knowledge:[],filters:{industries:[],locations:[],sizes:[],signal:'All signals',keyword:'',roles:'',productId:''},discoveries:[],accounts:[],research:[],leads:[],campaigns:[],activeCampaign:'',creditsUsed:0,events:[],settings:{}});
let state;try{state={...emptyState(),...JSON.parse(localStorage.getItem(STORE)||'null')}}catch{state=emptyState()}if(!state||!Array.isArray(state.products))state=emptyState();
let ui={page:'overview',modal:null,leo:false,sidebar:false,discoveryRunning:false,runMessage:'',resultsTab:'all',selectedAccounts:[],selectedLeads:[],productTab:'detail',selectedProduct:null,campaignTab:'sequence',selectedStep:null,leadSearch:'',leadTab:'contacts',campaignSearch:'',leoMessages:[],toastTimer:null};
const navItems=[{id:'overview',title:'Overview',icon:'grid',group:'WORKSPACE'},{id:'products',title:'Products & Knowledge',icon:'box',group:'WORKSPACE'},{id:'targets',title:'Target Prospects',icon:'target',group:'PROSPECTING'},{id:'pic',title:'AI PIC Finder',icon:'users',group:'PROSPECTING'},{id:'database',title:'Lead Database',icon:'database',group:'PROSPECTING'},{id:'campaigns',title:'Campaigns',icon:'send',group:'OUTREACH'},{id:'templates',title:'Templates',icon:'layers',group:'OUTREACH'},{id:'analytics',title:'Analytics',icon:'chart',group:'OUTREACH'},{id:'settings',title:'Settings & Billing',icon:'settings',group:'ACCOUNT'}];
function save(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch(e){console.warn('Storage full',e)}}
function product(){return state.products.find(x=>x.id===(state.filters.productId||state.productId))||state.products[0]||null}
function activeCampaign(){return state.campaigns.find(x=>x.id===state.activeCampaign)||null}
function countVerified(){return state.leads.filter(x=>x.verified).length}
function toast(msg){let el=document.getElementById('toast-area');if(!el)return;el.innerHTML=`<div class="toast">${ic('checkcircle',16)} ${esc(msg)}</div>`;clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>{if(el)el.innerHTML=''},3600)}
function navigate(page){ui.page=page;ui.sidebar=false;ui.modal=null;ui.selectedStep=null;ui.campaignTab='sequence';render();window.scrollTo(0,0)}
function shell(){const mark=esc((state.company||'W').slice(0,1).toUpperCase());let prev='';return `<div class="shell"><div class="mobile-backdrop ${ui.sidebar?'open':''}" data-act="toggleMenu"></div><aside class="sidebar ${ui.sidebar?'open':''}"><div class="brand"><img class="prospecto-brand-logo" alt="Prospecto by Elenio" src="assets/prospecto-logo-approved.png"/></div><div class="workspace"><div class="workspace-mark">${mark}</div><div class="grow" style="min-width:0"><strong>${esc(state.company)}</strong><small>Growth Workspace</small></div>${ic('down',12)}</div><div class="side-nav">${navItems.map(item=>{const group=prev!==item.group?`<div class="nav-label">${item.group}</div>`:'';prev=item.group;let count=item.id==='database'&&state.leads.length?`<span class="nav-count">${state.leads.length}</span>`:item.id==='campaigns'&&state.campaigns.length?`<span class="nav-count">${state.campaigns.length}</span>`:'';return group+`<button class="nav-btn ${ui.page===item.id||ui.page==='builder'&&item.id==='campaigns'?'active':''}" data-page="${item.id}">${ic(item.icon)} ${item.title}${count}</button>`}).join('')}</div><div class="side-bottom"><div class="credit-widget"><strong>Growth plan · Rp999.000/mo</strong><p>Research usage: ${state.creditsUsed} / 200 credits</p><div class="meter"><i style="width:${Math.min(100,state.creditsUsed/2)}%"></i></div></div></div></aside><div class="main"><header class="topbar"><div class="flex"><button class="icon-btn mobile-menu" data-act="toggleMenu" aria-label="Open navigation">${ic('menu')}</button><div class="crumb"><span class="trail">PROSPECTO</span><span class="trail">${ic('chevron',12)}</span><b>${ui.page==='builder'?'Campaign Builder':navItems.find(x=>x.id===ui.page)?.title||'Overview'}</b></div></div><div class="right-head"><button class="btn btn-soft btn-sm" data-act="openLeo">${ic('spark',15)} <span>Ask LEO</span></button><button class="icon-btn only-wide" data-page="settings" title="Settings">${ic('settings',17)}</button><div class="avatar">${mark}</div></div></header><main class="content fade-in">${route()}</main></div></div>${ui.modal?renderModal():''}${ui.leo?leoDrawer():''}<div id="toast-area" class="toast-wrap"></div>`}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-header"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`}
function empty(icon,title,desc,action=''){return `<div class="empty"><div class="empty-icon">${ic(icon,24)}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`}
function kpi(icon,value,label){return `<div class="card kpi"><div class="kpi-icon">${ic(icon,19)}</div><b>${value}</b><small>${label}</small></div>`}
function route(){switch(ui.page){case 'overview':return overview();case 'products':return productsPage();case 'targets':return targetsPage();case 'pic':return picPage();case 'database':return databasePage();case 'campaigns':return campaignsPage();case 'templates':return templatesPage();case 'builder':return builderPage();case 'analytics':return analyticsPage();case 'settings':return settingsPage();default:return overview()}}
function overview(){let next=!state.products.length?{t:'Tambahkan produk pertama Anda',desc:'Masukkan spesifikasi produk agar LEO dapat menyarankan target yang relevan.',button:'Setup produk',page:'products'}:!state.accounts.length?{t:'Temukan perusahaan yang tepat',desc:'Atur industri, ukuran, dan wilayah. Jalankan AI discovery setelah filter siap.',button:'Cari prospects',page:'targets'}:!state.leads.length?{t:'Lengkapi buying committee',desc:'Cari posisi PIC pada akun yang sudah dipilih dan lengkapi data kontak.',button:'Cari PIC',page:'pic'}:!state.campaigns.length?{t:'Siapkan campaign pertama',desc:'Gunakan template atau minta LEO menyusun sequence sesuai produk.',button:'Create campaign',page:'campaigns'}:{t:'Pipeline siap dikelola',desc:'Tinjau audience, perbarui campaign, dan pantau progres prospecting.',button:'Buka campaigns',page:'campaigns'};return `${heading('YOUR WORKSPACE','Good to see you.','Kelola seluruh aktivitas prospecting dan campaign dari satu tempat.')}
<div class="hero"><div class="hero-copy"><div class="eyebrow">NEXT BEST ACTION</div><h2>${next.t}</h2><p>${next.desc}</p><button class="btn" data-page="${next.page}">${next.button} ${ic('arrow',16)}</button></div><div class="hero-graph"><div class="hero-node">${ic('box',27)}</div><div class="progress-dot"></div><div class="hero-node">${ic('target',27)}</div><div class="progress-dot"></div><div class="hero-node">${ic('send',27)}</div></div></div>
<div class="section-row"><h3>Workspace snapshot</h3><span class="subtle">Summary aktivitas workspace</span></div><div class="grid4">${kpi('box',state.products.length,'Products defined')}${kpi('building',state.accounts.length,'Qualified accounts')}${kpi('users',state.leads.length,'Contacts saved')}${kpi('send',state.campaigns.length,'Campaign drafts')}</div>
<div class="section-row"><h3>Quick actions</h3></div><div class="grid3"><button class="action-card" data-page="targets"><span class="action-symbol">${ic('target',20)}</span><span><strong>Find prospects</strong><small>Filter perusahaan, jalankan AI discovery, lalu simpan shortlist.</small></span></button><button class="action-card" data-page="database"><span class="action-symbol">${ic('upload',20)}</span><span><strong>Import leads</strong><small>Unggah CSV atau Excel sebagai audience campaign.</small></span></button><button class="action-card" data-page="campaigns"><span class="action-symbol">${ic('spark',20)}</span><span><strong>Build a campaign</strong><small>Buat sequence dari template atau rekomendasi LEO.</small></span></button></div>
<div class="grid2" style="margin-top:19px"><div class="card card-pad"><div class="card-h"><h3>Prospecting pipeline</h3><button class="link-btn" data-page="analytics">View analytics ${ic('arrow',12)}</button></div>${[['Accounts',state.accounts.length,state.accounts.length?100:0],['Research tasks',state.research.length,Math.min(100,Math.round(100*state.research.length/Math.max(state.accounts.length,1)))],['Verified PICs',countVerified(),Math.min(100,Math.round(100*countVerified()/Math.max(state.leads.length,1)))]].map(x=>`<div class="funnel-row"><span>${x[0]}</span><div class="funnel-track"><i style="width:${x[2]}%"></i></div><strong>${x[1]}</strong></div>`).join('')}</div><div class="card card-pad"><div class="card-h"><h3>Recent activity</h3><span class="badge">${state.events.length} events</span></div>${state.events.length?state.events.slice(-4).reverse().map(x=>`<div class="activity-row"><div class="activity-icon">${ic(x.icon||'check',16)}</div><div><strong>${esc(x.title)}</strong><small>${esc(x.date)}</small></div></div>`).join(''):empty('clock','Aktivitas terbaru','Mulai dengan menambahkan produk atau menjalankan prospect discovery.')}</div></div>`}
function noteEvent(title,iconName='check'){state.events.push({id:id(),title,date:new Date().toLocaleString('id-ID'),icon:iconName});state.events=state.events.slice(-60)}
function productsPage(){let p=state.products.find(x=>x.id===(ui.selectedProduct||state.productId))||state.products[0];return `${heading('PRODUCT WORKSPACE','Products & Knowledge','Definisikan produk atau jasa perusahaan Anda. Informasi ini dipakai untuk ICP, riset PIC, dan campaign.',`<button class="btn btn-primary" data-act="newProduct">${ic('plus')} Add product</button>`)}<div class="grid2" style="grid-template-columns:minmax(260px,390px) minmax(0,1fr)"><div class="card card-pad"><div class="card-h"><h3>Product catalog</h3><span class="badge">${state.products.length} products</span></div>${state.products.length?`<div class="product-list">${state.products.map(x=>`<button class="product-card ${p?.id===x.id?'active':''}" data-act="selectProduct" data-id="${x.id}"><span class="product-icon">${ic('box',19)}</span><span class="grow"><strong>${esc(x.name)}</strong><small>${esc(x.category||'B2B offering')}</small></span>${p?.id===x.id?ic('check',15):ic('chevron',15)}</button>`).join('')}</div>`:empty('box','Belum ada produk','Mulai dari satu produk atau layanan yang ingin Anda jual.',`<button class="btn btn-primary btn-sm" data-act="newProduct">Add your first product</button>`)}</div><div class="card card-pad">${p?`<div class="card-h"><div><h3>${esc(p.name)}</h3><p>${esc(p.category||'Offering')}</p></div><button class="btn btn-sm" data-act="editProduct" data-id="${p.id}">${ic('pencil',14)} Edit</button></div><div class="tabs"><button class="tab ${ui.productTab==='detail'?'active':''}" data-act="productTab" data-id="detail">Specification</button><button class="tab ${ui.productTab==='knowledge'?'active':''}" data-act="productTab" data-id="knowledge">Knowledge Base <span class="badge">${state.knowledge.filter(k=>k.productId===p.id).length}</span></button></div>${ui.productTab==='detail'?`<div class="detail-line"><b>Target industry</b><span>${esc(p.industry||'Not defined')}</span></div><div class="detail-line"><b>Buyer persona</b><span>${esc(p.roles||'Not defined')}</span></div><div class="detail-line"><b>Customer problem</b><span>${esc(p.pain||'Not defined')}</span></div><div class="detail-line"><b>Value proposition</b><span>${esc(p.value||'Not defined')}</span></div><div class="detail-line"><b>Price / offering</b><span>${esc(p.pricing||'Not defined')}</span></div>`:`<div class="card-h"><div><h3>Knowledge sources</h3><p>Case studies, FAQ, positioning, proposals, dan URLs.</p></div><button class="btn btn-sm" data-act="addKnowledge" data-id="${p.id}">${ic('plus',14)} Add source</button></div><div class="knowledge-list">${state.knowledge.filter(k=>k.productId===p.id).map(k=>`<div class="knowledge-item"><div class="icbox">${ic(k.type==='URL'?'globe':'file')}</div><div class="grow"><strong>${esc(k.title)}</strong><small>${esc(k.type)} · ${esc(k.desc||'Stored metadata')}</small></div><button class="icon-btn" data-act="removeKnowledge" data-id="${k.id}" title="Remove">${ic('trash',14)}</button></div>`).join('')||empty('folder','Knowledge belum ditambahkan','Tambahkan dokumen, URL, atau teks agar LEO memahami produk Anda.')}</div>`}`:empty('box','Select a product','Detail spesifikasi dan knowledge akan tampil di sini setelah produk ditambahkan.')}</div></div><div class="callout" style="margin-top:15px">${ic('info',15)} <strong>How it works:</strong> Product Knowledge Base adalah konteks untuk target prospect matching, rekomendasi buying committee, dan personalized outreach. Tambahkan dokumen, FAQ, use case, dan penawaran sebagai konteks untuk pencarian prospek dan rekomendasi LEO.</div>`}
function targetsPage(){const f=state.filters;const p=product();let rs=state.discoveries;const saved=new Set(state.accounts.map(x=>x.company.toLowerCase()));const picked=ui.selectedAccounts.filter(x=>rs.some(y=>y.id===x));return `${heading('PROSPECT DISCOVERY','Target Prospects','Filter perusahaan ideal, lalu jalankan AI untuk menyusun daftar account yang relevan.',`<button class="btn" data-page="database">${ic('database',15)} Lead database</button>`)}
<div class="filter-layout"><div class="card filter-panel"><div class="filter-head"><div class="flex between"><h3 style="margin:0">Target filters</h3><button class="link-btn" data-act="resetFilters">Reset</button></div><p style="font-size:11px;margin:7px 0 0">Atur buyer profile sebelum discovery.</p></div><div class="filter-inner"><div class="filter-section"><div class="filter-title">Product to sell ${ic('box',13)}</div><select class="field" id="targetProduct"><option value="">${state.products.length?'Select product':'No product selected'}</option>${state.products.map(x=>`<option value="${x.id}" ${f.productId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${!state.products.length?`<button class="link-btn" data-page="products">+ Add product first</button>`:''}</div>
<div class="filter-section"><div class="filter-title">Industry <span class="badge">${f.industries.length||'All'}</span></div><div class="select-list">${industries.map(x=>`<button class="chip ${f.industries.includes(x)?'selected':''}" data-act="toggleIndustry" data-id="${esc(x)}">${esc(x)}</button>`).join('')}</div></div>
<div class="filter-section"><div class="filter-title">Location <span class="badge">${f.locations.length||'All'}</span></div><div class="select-list">${cities.slice(0,-1).map(x=>`<button class="chip ${f.locations.includes(x)?'selected':''}" data-act="toggleLocation" data-id="${esc(x)}">${esc(x)}</button>`).join('')}</div></div>
<div class="filter-section"><div class="filter-title">Company size</div><div class="select-list">${sizes.map((x,i)=>`<button class="chip ${i===0?!f.sizes.length:f.sizes.includes(x)?'selected':''}" data-act="selectSize" data-id="${esc(x)}">${esc(x)}</button>`).join('')}</div></div>
<div class="filter-section"><div class="filter-title">Buying signals</div><select class="field" id="filterSignal">${signals.map(x=>`<option ${f.signal===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div>
<details class="filter-section"><summary style="font-size:11px;font-weight:750;cursor:pointer;color:#355575">More filters</summary><div class="stack" style="margin-top:15px"><div class="field-group"><label>Keyword / domain focus</label><input id="filterKeyword" class="field" placeholder="e.g. security, operations" value="${esc(f.keyword)}"/></div><div class="field-group"><label>Target PIC titles</label><input id="filterRoles" class="field" placeholder="e.g. COO, Head of IT" value="${esc(f.roles)}"/></div></div></details></div><div class="filter-action"><button class="btn btn-primary" data-act="runDiscovery" ${ui.discoveryRunning?'disabled':''}>${ic(ui.discoveryRunning?'clock':'spark',16)} ${ui.discoveryRunning?'AI is working...':'Find prospects · 10 credits'}</button><p style="font-size:10px;margin:9px 0 0;text-align:center;color:#8598b0">Estimated 1 credit per researched account</p></div></div>
<div class="stack"><div class="runbox"><div><strong>${ui.discoveryRunning?'Research in progress':rs.length?'Discovery completed':'Ready to discover'}</strong><p>${ui.discoveryRunning?'Applying ICP filters and preparing prospect candidates.':rs.length?`${rs.length} accounts match your latest filters. Review their fit before adding to your shortlist.`:'Review your filters, then ask AI to search potential companies based on your ICP.'}</p>${ui.discoveryRunning?'<div class="run-progress"><i></i></div>':''}</div><div class="badge blue">${ic('spark',13)} AI prospect research</div></div>
<div class="card" style="overflow:hidden"><div class="card-h" style="padding:19px 20px 0;margin-bottom:11px"><div><h3>Discovery results</h3><p>${rs.length?`${rs.length} matching companies · Select accounts to shortlist`:'Mulai pencarian untuk menemukan perusahaan sesuai target Anda.'}</p></div>${rs.length?`<div class="flex"><span class="badge blue">${picked.length} selected</span><button class="btn btn-primary btn-sm" data-act="saveSelected" ${picked.length?'':'disabled'}>${ic('bookmark',14)} Save to shortlist</button></div>`:''}</div>${rs.length?`<div class="table-wrap"><table class="table"><thead><tr><th><input class="check" type="checkbox" id="allDiscoveries" aria-label="Select all" ${picked.length===rs.length?'checked':''}/></th><th>Company</th><th>Industry / location</th><th>Signal</th><th>Fit</th><th>Action</th></tr></thead><tbody>${rs.map(a=>`<tr><td><input class="check" type="checkbox" data-select-account="${a.id}" ${ui.selectedAccounts.includes(a.id)?'checked':''}/></td><td><strong>${esc(a.company)}</strong><span class="sub">${esc(a.size)} employees · ${esc(a.source)}</span></td><td>${esc(a.industry)}<span class="sub">${esc(a.location)}</span></td><td><span class="badge">${esc(a.signal)}</span></td><td><span class="score">${a.score}<i><b style="width:${a.score}%"></b></i></span></td><td><button class="btn btn-mini ${saved.has(a.company.toLowerCase())?'btn-soft':''}" data-act="saveAccount" data-id="${a.id}">${saved.has(a.company.toLowerCase())?ic('check',12):ic('plus',12)} ${saved.has(a.company.toLowerCase())?'Saved':'Shortlist'}</button></td></tr>`).join('')}</tbody></table></div>`:empty('search','Prospek sesuai filter akan muncul di sini','Use the filters to describe your ideal customers. The AI discovery will populate this table.',`<button class="btn btn-soft" data-act="runDiscovery">${ic('spark',15)} Run AI discovery</button>`)}<div style="border-top:1px solid var(--line);padding:12px 20px;display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><span class="source-note">${ic('info',13)} Pilih perusahaan yang sesuai dengan ICP, lalu lanjutkan ke riset decision maker.</span>${state.accounts.length?`<button class="link-btn" data-page="pic">${state.accounts.length} shortlisted → AI PIC Finder ${ic('arrow',13)}</button>`:''}</div></div>
${state.accounts.length?`<div class="card card-pad"><div class="card-h"><h3>Shortlisted accounts</h3><span class="badge green">${state.accounts.length} saved</span></div><div class="flex wrap">${state.accounts.slice(-7).reverse().map(a=>`<span class="badge outline">${ic('building',12)} ${esc(a.company)}</span>`).join('')}</div><div style="margin-top:17px"><button class="btn btn-primary btn-sm" data-page="pic">Research PICs ${ic('arrow',13)}</button></div></div>`:''}
</div></div>`}
function applyDiscovery(){if(ui.discoveryRunning)return;ui.discoveryRunning=true;ui.selectedAccounts=[];ui.runMessage='';render();setTimeout(()=>{const f=state.filters;let matches=directory.filter(x=>(!f.industries.length||f.industries.includes(x.industry))&&(!f.locations.length||f.locations.includes(x.location))&&(!f.sizes.length||f.sizes.includes(x.size))&&(!f.signal||f.signal==='All signals'||f.signal===x.signal)&&(!f.keyword||`${x.company} ${x.industry} ${x.signal}`.toLowerCase().includes(f.keyword.toLowerCase())));let p=product(),prodIndustry=(p?.industry||'').toLowerCase();matches=matches.map(x=>({...x,score:Math.min(98,65+(f.industries.length?11:3)+(f.locations.length?6:2)+(f.sizes.length?6:2)+(f.signal!=='All signals'?5:0)+(prodIndustry.includes(x.industry.toLowerCase())?7:0))})).sort((a,b)=>b.score-a.score);state.discoveries=matches;ui.discoveryRunning=false;noteEvent(`Prospect discovery: ${matches.length} candidates`,'spark');save();render();toast(matches.length?`${matches.length} potential accounts found`:'No results. Try adjusting your filters.')},950)}
function shortlist(a){if(!a)return false;if(state.accounts.some(x=>x.company.toLowerCase()===a.company.toLowerCase()))return false;state.accounts.push({id:id(),company:a.company,industry:a.industry,location:a.location,size:a.size,signal:a.signal,score:a.score,source:a.source,created:new Date().toISOString()});return true}
function picPage(){let roles=((state.filters.roles||product()?.roles||'Head of Operations, Head of IT, Procurement').split(',').map(x=>x.trim()).filter(Boolean));if(!roles.length)roles=['Head of Operations','Head of IT','Procurement'];const queued=state.research,done=queued.filter(x=>x.status==='Contact added').length;return `${heading('BUYING COMMITTEE','AI PIC Finder','Cari jabatan pengambil keputusan yang relevan, telusuri sumber publik, dan verifikasi kontak sebelum outreach.',`<button class="btn" data-page="database">${ic('database',15)} Open database</button><button class="btn btn-primary" data-act="generatePIC">${ic('spark',15)} Research PIC roles</button>`)}
<div class="grid3">${kpi('building',state.accounts.length,'Shortlisted companies')}${kpi('users',queued.length,'Research tasks')}${kpi('shield',done,'Verified tasks')}</div>
<div class="grid2" style="grid-template-columns:minmax(0,1.7fr) minmax(245px,1fr);margin-top:18px"><div class="card card-pad"><div class="card-h"><div><h3>Research queue</h3><p>Buying committee mapped to each shortlisted account.</p></div><button class="btn btn-sm" data-act="addPIC">${ic('plus',14)} Add contact</button></div>${queued.length?`<div class="table-wrap"><table class="table" style="min-width:540px"><thead><tr><th>Account</th><th>Suggested role</th><th>Status</th><th>Research</th></tr></thead><tbody>${queued.map(q=>`<tr><td><strong>${esc(q.company)}</strong></td><td>${esc(q.role)}</td><td><span class="badge ${q.status==='Contact added'?'green':'amber'}">${q.status==='Contact added'?'Contact added':'Needs verification'}</span></td><td><div class="flex"><button class="btn btn-mini" data-act="publicSearch" data-id="${q.id}" title="Public web search">${ic('globe',12)} Web</button><button class="btn btn-mini" data-act="linkedInSearch" data-id="${q.id}" title="Open LinkedIn search">in</button><button class="btn btn-mini btn-soft" data-act="addPIC" data-id="${q.id}">${ic('plus',12)} PIC</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('users','Start PIC research','Save target companies first, then generate recommended buyer roles for each account.',`<button class="btn btn-soft btn-sm" data-page="targets">${ic('target',14)} Find target companies</button>`)}</div>
<div class="stack"><div class="card card-pad"><div class="card-h"><h3>Recommended buyer roles</h3><span class="badge blue">${ic('spark',12)} LEO</span></div><div class="roles-grid" style="grid-template-columns:1fr">${roles.slice(0,5).map((r,i)=>`<div class="rolebox"><span class="pill-num">0${i+1}</span><span><strong>${esc(r)}</strong><small>${i===0?'Primary decision maker':i===1?'Technical evaluator':'Buying committee member'}</small></span></div>`).join('')}</div><button class="btn btn-soft btn-sm" data-act="openLeo" style="margin-top:16px;width:100%">${ic('spark',14)} Ask LEO about PIC strategy</button></div><div class="callout">${ic('shield',16)} <strong>Source-based discovery:</strong> Sumber web publik dapat membantu menemukan nama dan jabatan. Nama, profil, atau email tidak dibuat otomatis tanpa bukti. Selalu verifikasi nama, jabatan, dan sumber kontak sebelum outreach.</div></div></div>`}
function generatePIC(){if(!state.accounts.length){navigate('targets');toast('Shortlist target companies first');return}let p=product(),roles=(state.filters.roles||p?.roles||'Head of Operations, Head of IT, Procurement').split(',').map(x=>x.trim()).filter(Boolean).slice(0,4);let existing=new Set(state.research.map(q=>q.company+'|'+q.role));let added=0;state.accounts.forEach(a=>roles.forEach(role=>{if(!existing.has(a.company+'|'+role)){state.research.push({id:id(),company:a.company,role,status:'Pending research',source:''});added++}}));noteEvent(`${added} PIC research tasks prepared`,'users');save();render();toast(added?`${added} research tasks created`:'All roles are already in the queue')}
function databasePage(){let list=state.leads.filter(x=>`${x.company} ${x.name} ${x.role} ${x.email}`.toLowerCase().includes(ui.leadSearch.toLowerCase()));return `${heading('SALES DATA','Lead Database','Kelola perusahaan, PIC, dan audience. Impor Excel/CSV lalu validasi sebelum dipakai campaign.',`<button class="btn" data-act="downloadSample">${ic('file',15)} CSV template</button><button class="btn" data-act="importData">${ic('upload',15)} Import Excel / CSV</button><button class="btn btn-primary" data-act="addPIC">${ic('plus',15)} Add contact</button>`)}<div class="grid3">${kpi('building',state.accounts.length,'Accounts')}${kpi('users',state.leads.length,'Contacts')}${kpi('shield',countVerified(),'Verified contacts')}</div>
<div class="card" style="margin-top:18px"><div class="card-h" style="padding:20px 20px 0"><div><h3>Audience library</h3><p>All records stay in this workspace.</p></div><div class="flex"><input class="field" style="max-width:220px" id="leadSearch" placeholder="Search records..." value="${esc(ui.leadSearch)}"/><button class="btn btn-sm" data-act="exportLeads">${ic('upload',13)} Export</button></div></div><div class="tabs" style="padding-left:16px"><button class="tab ${ui.leadTab==='contacts'?'active':''}" data-act="leadTab" data-id="contacts">Contacts (${state.leads.length})</button><button class="tab ${ui.leadTab==='accounts'?'active':''}" data-act="leadTab" data-id="accounts">Accounts (${state.accounts.length})</button></div>${ui.leadTab==='contacts'?(list.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Company</th><th>Role</th><th>Email</th><th>Verification</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td><strong>${esc(x.name||'—')}</strong></td><td>${esc(x.company)}</td><td>${esc(x.role||'—')}</td><td>${esc(x.email||'Not available')}</td><td><span class="badge ${x.verified?'green':'amber'}">${x.verified?'Verified':'Unverified'}</span></td><td><button class="btn btn-mini" data-act="editContact" data-id="${x.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('database','No contacts saved','Upload a database or add PICs after checking their source and contact details.',`<button class="btn btn-primary btn-sm" data-act="importData">${ic('upload',14)} Import database</button>`)):(state.accounts.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Company</th><th>Industry</th><th>Location</th><th>Size</th><th>Source</th></tr></thead><tbody>${state.accounts.map(x=>`<tr><td><strong>${esc(x.company)}</strong></td><td>${esc(x.industry||'—')}</td><td>${esc(x.location||'—')}</td><td>${esc(x.size||'—')}</td><td><span class="badge">${esc(x.source||'Manual import')}</span></td></tr>`).join('')}</tbody></table></div>`:empty('building','No accounts saved','Shortlist companies from Target Prospects or import a database.'))}</div><div class="callout" style="margin-top:15px">${ic('info',15)} Kontak yang belum diverifikasi tetap tersimpan, tetapi campaign launch perlu melakukan review channel, izin, dan validitas data.</div>`}
function campaignsPage(){return `${heading('OUTREACH WORKSPACE','Campaigns','Buat, kelola, dan review sequence outreach dari satu workspace.',`<button class="btn" data-page="templates">${ic('layers',15)} Explore templates</button><button class="btn btn-primary" data-act="newCampaign">${ic('plus',15)} New campaign</button>`)}
${state.campaigns.length?`<div class="card card-pad"><div class="card-h"><div><h3>Your campaigns</h3><p>Select any campaign to edit its sequence and audience.</p></div><span class="badge">${state.campaigns.length} campaigns</span></div><div class="campaign-list">${state.campaigns.slice().reverse().map(c=>`<div class="campaign-row"><div class="flex"><span class="action-symbol" style="width:39px;height:39px;border-radius:10px;background:#eff6ff;color:#0a73e9;display:grid;place-items:center">${ic('send',18)}</span><div><strong>${esc(c.name)}</strong><small>${esc(state.products.find(x=>x.id===c.productId)?.name||'No product')} · ${c.steps.length} sequence steps · ${c.audience?.length||0} leads</small></div></div><div class="flex"><span class="badge ${c.status==='Ready'?'green':'amber'}">${esc(c.status||'Draft')}</span><button class="btn btn-sm" data-act="openCampaign" data-id="${c.id}">Open builder ${ic('arrow',13)}</button></div></div>`).join('')}</div></div>`:empty('send','Create your first campaign','Start from a proven B2B template, a blank sequence, or let LEO recommend a strategy based on your product.',`<div class="flex" style="justify-content:center"><button class="btn" data-page="templates">Browse templates</button><button class="btn btn-primary" data-act="newCampaign">${ic('plus',14)} New campaign</button></div>`)}
<div class="section-row"><h3>Start from a playbook</h3><button class="link-btn" data-page="templates">All templates ${ic('arrow',13)}</button></div><div class="grid3">${campaignsTemplates.slice(0,3).map(t=>templateCard(t)).join('')}</div>`}
function templateCard(t){return `<div class="card template"><div class="symbol">${ic(t.icon,21)}</div><div><h3>${esc(t.name)}</h3><p style="margin-top:6px">${esc(t.desc)}</p></div><div class="flex between"><span class="badge">${t.steps.length} steps</span><button class="btn btn-sm" data-act="useTemplate" data-id="${t.id}">Use template ${ic('arrow',13)}</button></div></div>`}
function templatesPage(){return `${heading('CAMPAIGN LIBRARY','Campaign Templates','Pilih playbook yang sesuai dengan buying journey, lalu sesuaikan email, kondisi, dan follow-up.',`<button class="btn btn-primary" data-act="newCampaign">${ic('plus',15)} Blank campaign</button>`)}<div class="templates">${campaignsTemplates.map(templateCard).join('')}</div><div class="callout" style="margin-top:20px">${ic('spark',15)} <strong>LEO can personalize templates.</strong> Sesuaikan pesan dengan KMS produk, buyer persona, dan daftar kontak yang Anda pilih. Semua sequence perlu ditinjau sebelum aktivasi.</div>`}
function buildSteps(templateId){let t=campaignsTemplates.find(x=>x.id===templateId)||campaignsTemplates[0],p=product();let title=p?.name||'[product]',pain=p?.pain||'[customer problem]',value=p?.value||'[value proposition]';return t.steps.map((name,i)=>({id:id(),type:/wait/i.test(name)?'wait':/condition/i.test(name)?'condition':/manual|task/i.test(name)?'task':'email',title:name,subject:i===0?`A thought for {{company}} about ${title}`:`Following up on ${title}`,body:i===0?`Hi {{first_name}},\n\nI noticed your team might be looking at ${pain}.\n\nAt ${state.company}, we help businesses with ${title}: ${value}.\n\nWould it make sense to exchange a few thoughts this week?\n\nBest,\n{{sender_name}}`:`Hi {{first_name}},\n\nFollowing up on my earlier note about ${title}. Would you be open to a short conversation?\n\nBest,\n{{sender_name}}`,days:/\d/.test(name)?Number(name.match(/\d+/)?.[0]||3):3,condition:'Has replied?'}))}
function makeCampaign(templateId='intro'){let p=product(),t=campaignsTemplates.find(x=>x.id===templateId),c={id:id(),name:t?`${t.name} · ${p?.name||'New offering'}`:'New outreach campaign',productId:p?.id||'',templateId:templateId||'',status:'Draft',steps:templateId?buildSteps(templateId):[],audience:[],created:new Date().toISOString()};state.campaigns.push(c);state.activeCampaign=c.id;ui.campaignTab='sequence';ui.selectedStep=null;noteEvent(`Campaign created: ${c.name}`,'send');save();navigate('builder')}
function stepIcon(type){return type==='email'?'mail':type==='condition'?'branch':type==='wait'?'clock':type==='task'?'users':'send'}
function builderPage(){let c=activeCampaign();if(!c){navigate('campaigns');return ''}let p=state.products.find(x=>x.id===c.productId),s=c.steps.find(x=>x.id===ui.selectedStep);return `${heading('CAMPAIGN WORKSPACE',esc(c.name),`${p?esc(p.name)+' · ':''}${c.steps.length} steps · ${c.audience?.length||0} leads · ${esc(c.status||'Draft')}`,`<button class="btn" data-act="renameCampaign">${ic('pencil',15)} Rename</button><button class="btn" data-act="saveDraft">${ic('check',15)} Save draft</button><button class="btn btn-soft" data-act="openLeo">${ic('spark',15)} Ask LEO</button>`)}
<div class="builder-tabs"><button class="${ui.campaignTab==='sequence'?'active':''}" data-act="campaignTab" data-id="sequence">01 · Sequence</button><button class="${ui.campaignTab==='audience'?'active':''}" data-act="campaignTab" data-id="audience">02 · Audience</button><button class="${ui.campaignTab==='review'?'active':''}" data-act="campaignTab" data-id="review">03 · Review</button><button class="${ui.campaignTab==='performance'?'active':''}" data-act="campaignTab" data-id="performance">04 · Performance</button></div>
${ui.campaignTab==='sequence'?`<div class="builder-layout"><div><div class="canvas"><div class="canvas-top"><div class="flex"><span class="badge blue">${ic('branch',13)} Sequence builder</span><span class="subtle">Edit steps to personalize outreach</span></div><div class="builder-toolbar"><button class="btn btn-sm" data-act="addStep" data-id="email">${ic('plus',13)} Email</button><button class="btn btn-sm" data-act="addStep" data-id="wait">${ic('clock',13)} Wait</button><button class="btn btn-sm" data-act="addStep" data-id="condition">${ic('branch',13)} If / Else</button><button class="btn btn-sm" data-act="addStep" data-id="task">${ic('users',13)} Task</button></div></div>${c.steps.length?`<div class="node-flow"><div class="node" style="cursor:default"><div class="node-symbol">${ic('play')}</div><div class="node-content"><b>Sequence start</b><p>Trigger: audience entered campaign</p></div><span class="badge green">Start</span></div><div class="connector"></div>${c.steps.map((step,i)=>`<div class="node ${ui.selectedStep===step.id?'selected':''}" data-act="selectStep" data-id="${step.id}"><span class="node-symbol">${ic(stepIcon(step.type),17)}</span><div class="node-content"><b>${esc(step.title)}</b><p>${step.type==='email'?esc(step.subject||'Edit message'):step.type==='wait'?`Wait ${step.days||3} day(s)`:step.type==='condition'?esc(step.condition||'Has replied?'):'Manual task / LinkedIn research'}</p></div><span class="badge">${i+1}</span></div>${step.type==='condition'?`<div class="connector" style="height:20px"></div><div class="branch"><div class="branch-card"><span class="badge green">Yes</span><div style="margin-top:9px">Continue / follow up</div></div><div class="branch-card"><span class="badge amber">No</span><div style="margin-top:9px">Continue sequence</div></div></div>`:''}<div class="connector"></div>`).join('')}<div class="node" style="cursor:default;border-style:dashed;background:#ffffffc9"><div class="node-symbol">${ic('checkcircle',17)}</div><div class="node-content"><b>End of sequence</b><p>Track response and conversion</p></div></div></div>`:empty('send','Start your sequence','Add email, wait, task, and condition steps. Or ask LEO for a suggested campaign.',`<button class="btn btn-primary btn-sm" data-act="leoPlan">${ic('spark',14)} Generate with LEO</button>`)}</div></div><div class="card inspector">${s?`<div class="card-h"><h3>Edit step</h3><span class="badge blue">${esc(s.type)}</span></div><div class="stack"><div class="field-group"><label>Step name</label><input class="field" data-step-field="title" value="${esc(s.title)}"/></div>${s.type==='email'?`<div class="field-group"><label>Subject line</label><input class="field" data-step-field="subject" value="${esc(s.subject||'')}"/></div><div class="field-group"><label>Message</label><textarea class="field" style="min-height:210px" data-step-field="body">${esc(s.body||'')}</textarea></div><div class="field-hint">Variables: {{first_name}}, {{company}}, {{sender_name}}</div>`:s.type==='wait'?`<div class="field-group"><label>Wait (days)</label><input class="field" type="number" min="1" max="60" data-step-field="days" value="${s.days||3}"/></div>`:s.type==='condition'?`<div class="field-group"><label>Condition</label><select class="field" data-step-field="condition">${['Has replied?','Has email address?','Contact verified?','Has company?'].map(x=>`<option ${s.condition===x?'selected':''}>${x}</option>`).join('')}</select></div>`:`<div class="field-group"><label>Task instructions</label><textarea class="field" data-step-field="body">${esc(s.body||'Research profile and personalize outreach manually.')}</textarea></div>`}<div class="flex"><button class="btn btn-primary btn-sm" data-act="saveStep">Save step</button><button class="btn btn-sm" data-act="removeStep" data-id="${s.id}">${ic('trash',13)} Remove</button></div></div>`:`<div class="card-h"><h3>Sequence assistant</h3><span class="badge blue">LEO</span></div><p style="font-size:11px">Select a step to edit its settings. You can also ask LEO to propose a sequence using your product knowledge.</p><button class="btn btn-soft" data-act="leoPlan">${ic('spark',15)} Suggest a sequence</button><hr class="divider"/><div class="stack"><div class="activity-row"><div class="activity-icon">${ic('mail',14)}</div><div><strong>Email</strong><small>Personalized outreach message</small></div></div><div class="activity-row"><div class="activity-icon">${ic('branch',14)}</div><div><strong>Conditions</strong><small>Branch by reply or email availability</small></div></div><div class="activity-row"><div class="activity-icon">${ic('users',14)}</div><div><strong>Manual tasks</strong><small>LinkedIn research and follow-up</small></div></div></div>`}</div></div><div style="display:flex;justify-content:flex-end;margin-top:15px"><button class="btn btn-primary" data-act="campaignTab" data-id="audience">Next: select audience ${ic('arrow',15)}</button></div>`:ui.campaignTab==='audience'?builderAudience(c):ui.campaignTab==='review'?builderReview(c):builderPerformance(c)}`}
function builderAudience(c){let selected=new Set(c.audience||[]);return `<div class="card card-pad"><div class="card-h"><div><h3>Choose campaign audience</h3><p>Only opted-in / appropriately sourced and verified contacts should be considered for delivery.</p></div><div class="flex"><span class="badge blue">${selected.size} selected</span><button class="btn btn-sm" data-page="database">${ic('upload',14)} Manage database</button></div></div>${state.leads.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Include</th><th>Name</th><th>Company</th><th>Role</th><th>Status</th></tr></thead><tbody>${state.leads.map(x=>`<tr><td><input class="check" type="checkbox" data-audience-id="${x.id}" ${selected.has(x.id)?'checked':''}/></td><td><strong>${esc(x.name||'—')}</strong></td><td>${esc(x.company)}</td><td>${esc(x.role)}</td><td><span class="badge ${x.verified?'green':'amber'}">${x.verified?'Verified':'Unverified'}</span></td></tr>`).join('')}</tbody></table></div>`:empty('database','Your audience is empty','Import leads or add contacts, then select who should be included in this campaign.',`<button class="btn btn-primary btn-sm" data-act="importData">${ic('upload',14)} Import leads</button>`)}</div><div class="flex" style="justify-content:flex-end;margin-top:15px"><button class="btn btn-primary" data-act="campaignTab" data-id="review">Next: review ${ic('arrow',14)}</button></div>`}
function reviewReadiness(c){let checks=[{label:'Product selected',ok:!!state.products.find(x=>x.id===c.productId),desc:'Campaign has a defined product context'},{label:'Sequence configured',ok:c.steps.length>0,desc:'At least one outreach step'},{label:'Audience selected',ok:(c.audience||[]).length>0,desc:'Contacts assigned to campaign'},{label:'Contact data reviewed',ok:c.audience?.length>0&&c.audience.every(x=>state.leads.some(l=>l.id===x&&l.verified)),desc:'Selected contacts are marked verified'},{label:'Sending channel connected',ok:false,desc:'Requires authenticated provider and backend approval'}];return checks}
function builderReview(c){let checks=reviewReadiness(c),ready=checks.filter(x=>x.ok).length;return `<div class="grid2" style="grid-template-columns:minmax(0,1.65fr) minmax(250px,1fr)"><div class="card card-pad"><div class="card-h"><h3>Launch review</h3><span class="badge ${ready===checks.length?'green':'amber'}">${ready} / ${checks.length} checks</span></div>${checks.map(x=>`<div class="activity-row"><div class="activity-icon" style="background:${x.ok?'#edf9f3':'#fff7ed'};color:${x.ok?'#16866a':'#c07b20'}">${ic(x.ok?'checkcircle':'clock',17)}</div><div class="grow"><strong>${esc(x.label)}</strong><small>${esc(x.desc)}</small></div><span class="badge ${x.ok?'green':'amber'}">${x.ok?'Ready':'Pending'}</span></div>`).join('')}<div style="margin-top:17px" class="callout warning">${ic('info',14)} Pastikan channel pengirim terhubung, data audience terverifikasi, dan izin komunikasi telah ditinjau sebelum campaign dijalankan.</div></div><div class="card card-pad"><h3 style="margin-bottom:17px">Campaign summary</h3><div class="detail-line"><b>Name</b><span>${esc(c.name)}</span></div><div class="detail-line"><b>Steps</b><span>${c.steps.length}</span></div><div class="detail-line"><b>Audience</b><span>${c.audience?.length||0}</span></div><div class="detail-line"><b>Status</b><span>${esc(c.status)}</span></div><div style="margin-top:20px" class="stack"><button class="btn btn-primary" data-act="saveDraft">${ic('check',15)} Save campaign draft</button><button class="btn" data-act="campaignTab" data-id="sequence">Back to sequence</button></div></div></div>`}
function builderPerformance(c){return `<div class="grid4">${kpi('users',c.audience?.length||0,'Assigned audience')}${kpi('send',0,'Emails sent')}${kpi('mail',0,'Replies')}${kpi('calendar',0,'Meetings')}</div><div class="card card-pad" style="margin-top:18px">${empty('chart','No delivery data yet','Pantau email terkirim, respons, meeting, dan peluang setelah campaign dijalankan.')}</div>`}
function analyticsPage(){
 const audience=state.campaigns.reduce((n,c)=>n+(c.audience?.length||0),0);
 const totalSteps=state.campaigns.reduce((n,c)=>n+c.steps.length,0);
 const totalResearch=state.research.length;
 const peak=Math.max(state.discoveries.length,state.accounts.length,totalResearch,state.leads.length,audience,1);
 return `${heading('PERFORMANCE','Analytics','Ringkasan prospecting, kualitas database, dan kesiapan campaign.',`<button class="btn" data-page="campaigns">${ic('send',14)} Lihat campaigns</button>`)}
 <div class="grid4">${kpi('building',state.accounts.length,'Qualified accounts')}${kpi('users',state.leads.length,'Contacts in database')}${kpi('send',state.campaigns.length,'Campaigns')}${kpi('clock',totalSteps,'Sequence steps')}</div>
 <div class="grid2" style="margin-top:17px">
 <div class="card card-pad"><div class="card-h"><h3>Prospecting funnel</h3><span class="badge">Workspace</span></div>
 ${[['Companies found',state.discoveries.length],['Shortlisted',state.accounts.length],['PIC research tasks',totalResearch],['Contacts',state.leads.length],['Campaign audience',audience]].map(x=>`<div class="funnel-row"><span style="width:135px">${x[0]}</span><div class="funnel-track"><i style="width:${x[1]?Math.max(4,100*x[1]/peak):0}%"></i></div><strong>${x[1]}</strong></div>`).join('')}</div>
 <div class="card card-pad"><div class="card-h"><h3>Campaign performance</h3><span class="badge amber">Menunggu aktivasi</span></div>
 <div class="v10-performance-tiles"><div><b>${audience}</b><small>Leads assigned</small></div><div><b>${totalSteps}</b><small>Sequence steps</small></div><div><b>${state.campaigns.length}</b><small>Draft campaigns</small></div></div>
 <div class="v10-caption">Hasil pengiriman, balasan, dan meeting akan tercatat setelah campaign dijalankan melalui akun pengirim yang terhubung.</div>
 </div></div>
 <div class="card card-pad" style="margin-top:17px"><div class="card-h"><h3>Campaign overview</h3><button class="link-btn" data-page="campaigns">Kelola campaigns ${ic('arrow',13)}</button></div><div class="v10-table-scroll"><table class="v10-table"><thead><tr><th>Campaign</th><th>Product</th><th>Audience</th><th>Sequence</th><th>Status</th></tr></thead><tbody>${state.campaigns.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(state.products.find(x=>x.id===c.productId)?.name||'—')}</td><td>${c.audience?.length||0} contacts</td><td>${c.steps.length} steps</td><td><span class="badge amber">${esc(c.status||'Draft')}</span></td></tr>`).join('')}</tbody></table></div></div>`;
}

let settingsPage; // Customer-only settings is defined by the v9 connected-accounts layer.
function renderModal(){let m=ui.modal;if(!m)return '';let title='',body='',foot='';const cancel='<button class="btn" data-act="closeModal">Cancel</button>';
 if(m.type==='product'){const p=state.products.find(x=>x.id===m.id)||{};title=p.id?'Edit product':'Add product';body=`<form id="productForm" class="stack"><div class="form-grid"><div class="field-group"><label>Product / service name *</label><input class="field" name="name" value="${esc(p.name||'')}" placeholder="e.g. Fleet Analytics Platform" required/></div><div class="field-group"><label>Category</label><select name="category" class="field">${['Software / SaaS','AI & Technology','Professional Services','Industrial Solution','Physical Products','Other'].map(x=>`<option ${p.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field-group span2"><label>Pain problem *</label><textarea class="field" name="pain" placeholder="Which costly, specific problem does your product solve?" required>${esc(p.pain||'')}</textarea></div><div class="field-group span2"><label>Value proposition *</label><textarea class="field" name="value" placeholder="Describe business outcomes, not generic features" required>${esc(p.value||'')}</textarea></div><div class="field-group"><label>Target industries</label><input class="field" name="industry" value="${esc(p.industry||'')}" placeholder="e.g. Logistics, Manufacturing"/></div><div class="field-group"><label>Ideal buyer roles</label><input class="field" name="roles" value="${esc(p.roles||'')}" placeholder="e.g. COO, Head of IT"/></div><div class="field-group span2"><label>Pricing / positioning</label><input class="field" name="pricing" value="${esc(p.pricing||'')}" placeholder="e.g. Subscription, enterprise contracts"/></div></div></form>`;foot=cancel+'<button type="submit" form="productForm" class="btn btn-primary">Save product</button>'}
 if(m.type==='knowledge'){title='Add knowledge source';body=`<form id="knowledgeForm" class="stack"><div class="field-group"><label>Source type</label><select class="field" name="type" id="knowledgeType"><option>Text / Notes</option><option>URL</option><option>File</option></select></div><div class="field-group"><label>Source name *</label><input class="field" name="title" placeholder="e.g. Product FAQ / Use case" required/></div><div class="field-group"><label>URL or notes</label><textarea class="field" name="desc" placeholder="Paste a reference URL or background information"></textarea></div><div class="field-group"><label>Attach document (PDF, DOCX, TXT)</label><input type="file" class="field" name="file" id="knowledgeFile" accept=".pdf,.docx,.txt,.md"/><span class="field-hint">Pada preview ini, dokumen dicatat sebagai referensi. Analisis isi dokumen tersedia setelah integrasi live.</span></div></form>`;foot=cancel+'<button class="btn btn-primary" type="submit" form="knowledgeForm">Save source</button>'}
 if(m.type==='pic'){let q=state.research.find(x=>x.id===m.id);let c=state.leads.find(x=>x.id===m.contactId)||{};let autoCompany=state.accounts.length===1?state.accounts[0].company:'';title=c.id?'Edit contact':'Add verified PIC';body=`<form id="picForm" class="stack"><div class="form-grid"><div class="field-group"><label>Full name *</label><input name="name" class="field" value="${esc(c.name||'')}" required placeholder="Person's published name"/></div><div class="field-group"><label>Company *</label><input name="company" class="field" value="${esc(c.company||q?.company||autoCompany)}" required placeholder="Company name"/></div><div class="field-group"><label>Job title</label><input name="role" class="field" value="${esc(c.role||q?.role||product()?.roles?.split(',')[0]||'')}" placeholder="Official title"/></div><div class="field-group"><label>Business email</label><input name="email" type="email" class="field" value="${esc(c.email||'')}" placeholder="name@company.com"/></div><div class="field-group span2"><label>Public profile URL (optional)</label><input name="linkedin" type="url" class="field" value="${esc(c.linkedin||'')}" placeholder="https://linkedin.com/in/..."/></div><div class="field-group span2"><label>Evidence / public source URL</label><input name="source" type="url" class="field" value="${esc(c.source||'')}" placeholder="https://company.com/team/..."/></div></div><label class="option-check"><input type="checkbox" name="verified" ${c.verified?'checked':''}/> Contact details reviewed against a reliable source</label><span class="field-hint">Never mark as verified without checking the source. Prospecto will not invent a real PIC name or email.</span></form>`;foot=cancel+'<button class="btn btn-primary" type="submit" form="picForm">Save contact</button>'}
 if(m.type==='import'){title='Import lead database';body=`<div class="stack"><label class="dropzone" for="uploadLeadFile">${ic('upload',27)}<strong>Choose CSV or XLSX file</strong><p>Lead list, buying committee, or company target database</p><input type="file" id="uploadLeadFile" accept=".csv,.xlsx,.xls"/></label><div class="callout">Supported fields: <strong>company, name, role, email, linkedin, industry, website</strong>. You can map columns before importing. Duplicate contacts are skipped.</div><button class="btn btn-sm" data-act="downloadSample">${ic('file',14)} Download CSV template</button></div>`;foot=cancel}
 if(m.type==='importPreview'){title='Review import mapping';let sample=ui.importMatrix?.slice(1,4)||[];let headers=ui.importMatrix?.[0]||[];const opts=['Ignore','Company','Name','Role','Email','LinkedIn','Industry','Website'];body=`<div class="stack"><div class="flex between"><p style="margin:0">${esc(ui.importName)} · ${Math.max(0,(ui.importMatrix?.length||1)-1)} rows</p><span class="badge blue">Column mapping</span></div><div class="form-grid">${headers.map((x,i)=>`<div class="field-group"><label>${esc(String(x))}</label><select class="field" data-map-col="${i}">${opts.map(y=>`<option ${ui.importMap?.[i]===y?'selected':''}>${y}</option>`).join('')}</select></div>`).join('')}</div><div class="field-hint">Tiga baris pertama</div><div class="table-wrap"><table class="table" style="min-width:550px"><thead><tr>${headers.map(x=>`<th>${esc(String(x))}</th>`).join('')}</tr></thead><tbody>${sample.map(r=>`<tr>${headers.map((_,i)=>`<td>${esc(String(r[i]??''))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;foot=cancel+'<button class="btn btn-primary" data-act="confirmImport">Import records</button>'}
 if(m.type==='renameCampaign'){title='Rename campaign';body=`<form id="renameCampaignForm"><div class="field-group"><label>Campaign name</label><input class="field" name="name" required value="${esc(activeCampaign()?.name||'')}"/></div></form>`;foot=cancel+'<button class="btn btn-primary" type="submit" form="renameCampaignForm">Save name</button>'}
 if(m.type==='newCampaign'){title='Create campaign';body=`<div class="stack"><p style="font-size:12px;margin:0 0 3px">Choose how you want to start.</p><button class="suggestion" data-act="createCampaign" data-id=""><span class="action-symbol">${ic('plus',19)}</span><span><strong>Blank sequence</strong><small>Build your own steps from scratch</small></span></button><button class="suggestion" data-act="createCampaign" data-id="pain"><span class="action-symbol">${ic('target',19)}</span><span><strong>LEO suggestion</strong><small>Pre-fill a consultative sequence from your current product context</small></span></button><button class="suggestion" data-act="selectTemplates"><span class="action-symbol">${ic('layers',19)}</span><span><strong>Choose a template</strong><small>Start from six reusable B2B playbooks</small></span></button></div>`;foot=cancel}
return `<div class="modal-shade" id="modalShade"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-act="closeModal" aria-label="Close">${ic('close',18)}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div></div>`}
function leoDrawer(){let p=product(),leadContext=p?`${p.name}: ${p.pain||p.value||'Product knowledge not yet complete'}`:'No product configured yet';return `<div class="drawer-overlay" id="leoShade" style="justify-content:flex-end;padding:0"><aside class="leo-drawer"><div class="leo-top"><div class="flex"><div class="kpi-icon" style="margin:0;background:#eaf3ff">${ic('spark',20)}</div><div><strong>LEO Sales Agent</strong><small>Campaign strategy & prospecting copilot</small></div></div><button class="icon-btn" data-act="closeLeo">${ic('close',17)}</button></div><div class="leo-body" id="leoMessages"><div class="leo-bubble bot">Hi! Saya LEO. Saya bisa membantu memilih ICP, menyusun buyer committee, dan membuat campaign berdasarkan Product KMS Anda.<br/><br/><strong>Product context:</strong> ${esc(leadContext)}</div>${ui.leoMessages.map(x=>`<div class="leo-bubble ${x.who==='you'?'me':'bot'}">${esc(x.text).replace(/\n/g,'<br/>')}</div>`).join('')}<div class="stack" style="margin-top:16px;gap:8px"><button class="suggestion" data-act="leoSuggestion" data-id="icp">${ic('target',16)} <div><strong>Suggest target ICP</strong><small>Industries, buyer profiles & filters</small></div></button><button class="suggestion" data-act="leoSuggestion" data-id="campaign">${ic('send',16)} <div><strong>Build outreach sequence</strong><small>Personalized campaign from product KMS</small></div></button><button class="suggestion" data-act="leoSuggestion" data-id="pic">${ic('users',16)} <div><strong>Find decision-maker roles</strong><small>Buying committee recommendation</small></div></button>${ui.page==='builder'?`<button class="btn btn-primary" style="width:100%" data-act="applyLEOSequence">${ic('check',14)} Apply LEO sequence to campaign</button>`:''}</div></div><div class="leo-input"><form id="leoForm"><input class="field" name="prompt" placeholder="Ask LEO about your sales strategy..." required/><button class="btn btn-primary" type="submit">${ic('arrow',17)}</button></form><div class="field-hint" style="margin-top:8px">Pada konsep HTML ini, LEO membuat saran berdasarkan data produk lokal.</div></div></aside></div>`}
function leoSuggestion(type){let p=product(),pain=p?.pain||'customer operational inefficiency',value=p?.value||'improved business outcomes',roles=(p?.roles||'COO, Head of IT, Procurement').split(',').map(x=>x.trim()).filter(Boolean),inds=p?.industry||'the most relevant B2B industries';let msg=type==='icp'?`ICP suggestion for ${p?.name||'your product'}:\n• Industries: ${inds}\n• Company size: 51–1,000 employees\n• Signal: Digital transformation or multi-site operations\n• Pain: ${pain}\n\nUse the Target Prospects menu to set filters and run discovery.`:type==='pic'?`Recommended buying committee:\n• Primary: ${roles[0]||'Head of Operations'}\n• Technical: ${roles[1]||'Head of IT'}\n• Commercial: ${roles[2]||'Procurement / Finance'}\n\nSearch publicly available sources and verify each contact before adding them to the lead database.`:`Recommended outreach:\n1. Email: mention ${pain}\n2. Wait 3 days\n3. If replied: assign follow-up task\n4. Else: share a specific use case\n5. Ask for a 15-minute discovery call\n\nValue angle: ${value}`;ui.leoMessages.push({who:'bot',text:msg});ui.leoMessages=ui.leoMessages.slice(-12);render();if(ui.leo){setTimeout(()=>{let el=document.getElementById('leoMessages');if(el)el.scrollTop=el.scrollHeight},30)}}
function sendLeo(prompt){ui.leoMessages.push({who:'you',text:prompt});let t=prompt.toLowerCase();leoSuggestion(/pic|decision|person|jabatan|buying/.test(t)?'pic':/target|icp|filter|industri|industry|prospect/.test(t)?'icp':'campaign')}
function selectedProductForModal(){return state.products.find(x=>x.id===ui.modal?.id)}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function saveProductForm(form){let x=formData(form),pid=ui.modal?.id||id();let existing=state.products.find(p=>p.id===pid);const obj={id:pid,name:String(x.name).trim(),category:x.category,pain:String(x.pain).trim(),value:String(x.value).trim(),industry:String(x.industry||'').trim(),roles:String(x.roles||'').trim(),pricing:String(x.pricing||'').trim()};if(existing)Object.assign(existing,obj);else state.products.push(obj);state.productId=pid;state.filters.productId=pid;ui.selectedProduct=pid;ui.modal=null;noteEvent(`Product saved: ${obj.name}`,'box');save();render();toast('Product saved')}
function saveKnowledgeForm(form){let x=formData(form);const file=form.querySelector('input[type="file"]')?.files?.[0];let pid=ui.modal?.id||product()?.id;if(!pid)return;state.knowledge.push({id:id(),productId:pid,type:file?'File':x.type,title:String(x.title||file?.name||'Knowledge source'),desc:String(x.desc||file?.name||'').slice(0,5000),filename:file?.name||'',added:new Date().toISOString()});ui.productTab='knowledge';ui.modal=null;noteEvent(`Knowledge source added`,'file');save();render();toast('Source added to knowledge list')}
function upsertImportedAccount(company,extras={}){let name=String(company||'').trim();if(!name)return null;let found=state.accounts.find(x=>x.company.toLowerCase()===name.toLowerCase());if(found)return found;let a={id:id(),company:name,industry:extras.industry||'',location:extras.location||'',size:'',signal:'',source:extras.source||'Imported database',score:0,created:new Date().toISOString()};state.accounts.push(a);return a}
function savePICForm(form){let x=formData(form),name=String(x.name||'').trim(),company=String(x.company||'').trim(),email=String(x.email||'').trim().toLowerCase();if(!name||!company){toast('Name and company are required');return}let existing=state.leads.find(l=>l.id===ui.modal?.contactId);let duplicate=state.leads.find(l=>l.id!==existing?.id&&(email?l.email===email:l.name.toLowerCase()===name.toLowerCase()&&l.company.toLowerCase()===company.toLowerCase()));if(duplicate){toast('This contact already exists');return}let obj={id:existing?.id||id(),name,company,role:String(x.role||''),email,linkedin:String(x.linkedin||''),source:String(x.source||''),verified:form.querySelector('[name="verified"]').checked};if(existing)Object.assign(existing,obj);else state.leads.push(obj);upsertImportedAccount(company,{source:'Contact database'});let q=state.research.find(q=>q.id===ui.modal?.id);if(q)q.status='Contact added';ui.modal=null;noteEvent(`PIC saved: ${name}`,'users');save();render();toast('Contact saved')}
function csvParse(text){const rows=[];let r=[],cell='',inside=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(inside&&text[i+1]==='"'){cell+='"';i++}else inside=!inside}else if(c===','&&!inside){r.push(cell);cell=''}else if((c==='\r'||c==='\n')&&!inside){if(c==='\r'&&text[i+1]==='\n')i++;r.push(cell);if(r.some(x=>String(x).trim()))rows.push(r);r=[];cell=''}else cell+=c}r.push(cell);if(r.some(x=>String(x).trim()))rows.push(r);return rows}
function inferMap(headers){const patterns={Company:/^(company|companyname|perusahaan|namaperusahaan|organization|account|business)$/i,Name:/^(name|fullname|pic|namapic|contact|contactname|nama)$/i,Role:/^(role|jobtitle|title|position|jabatan)$/i,Email:/^(email|emailaddress|businessemail|workemail)$/i,LinkedIn:/^(linkedin|linkedinurl|linkedinprofile|profileurl)$/i,Industry:/^(industry|sector|industri)$/i,Website:/^(website|domain|site)$/i};return headers.map(h=>{let n=String(h).replace(/[\s_-]/g,'');return Object.keys(patterns).find(x=>patterns[x].test(n))||'Ignore'})}
// Load optional XLSX support only when an Excel file is selected.
// The Prospecto interface and CSV import open without any internet connection.
let excelReaderPromise=null;
function loadExcelReader(){
  if(typeof XLSX!=='undefined')return Promise.resolve();
  if(excelReaderPromise)return excelReaderPromise;
  excelReaderPromise=new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';
    script.async=true;
    script.onload=()=>typeof XLSX!=='undefined'?resolve():reject(new Error('Excel reader tidak tersedia. Simpan file sebagai CSV.'));
    script.onerror=()=>reject(new Error('XLSX memerlukan koneksi internet saat diimpor. Gunakan CSV bila offline.'));
    document.head.appendChild(script);
  }).catch(err=>{excelReaderPromise=null;throw err});
  return excelReaderPromise;
}
async function readLeadFile(file){if(!file)return;try{let rows;if(file.name.toLowerCase().endsWith('.csv')){rows=csvParse(await file.text())}else if(/\.xlsx?$/i.test(file.name)){if(typeof XLSX==='undefined')await loadExcelReader();let wb=XLSX.read(await file.arrayBuffer(),{type:'array'});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:''})}else throw Error('Upload CSV or XLSX');if(rows.length<2)throw Error('File needs a header and at least one row');ui.importMatrix=rows.slice(0,5001);ui.importMap=inferMap(rows[0]);ui.importName=file.name;ui.modal={type:'importPreview'};render()}catch(e){toast(e.message||'Import error')}}
function confirmImport(){const map=ui.importMap||[],rows=ui.importMatrix||[];if(!map.includes('Company')&&!map.includes('Email')){toast('Map at least Company or Email');return}let contacts=0,accounts=0,duplicates=0;for(let r of rows.slice(1)){let x={};map.forEach((field,i)=>{if(field!=='Ignore')x[field]=String(r[i]??'').trim()});let company=x.Company||'';if(company){let before=state.accounts.length;upsertImportedAccount(company,{industry:x.Industry||'',source:'Excel / CSV import'});if(state.accounts.length>before)accounts++}if(x.Name||x.Email){let email=String(x.Email||'').toLowerCase();let dupe=state.leads.some(l=>email?l.email===email:l.name.toLowerCase()===(x.Name||'').toLowerCase()&&l.company.toLowerCase()===company.toLowerCase());if(dupe){duplicates++;continue}state.leads.push({id:id(),name:x.Name||'',company,role:x.Role||'',email,linkedin:x.LinkedIn||'',source:'Imported database',verified:false});contacts++}}ui.importMatrix=[];ui.importMap=[];ui.modal=null;noteEvent(`Import: ${contacts} contacts & ${accounts} accounts`,'upload');save();render();toast(`${contacts} contacts, ${accounts} accounts added · ${duplicates} duplicates skipped`)}
function csvDownload(rows,name){const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');let blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function publicLink(q,linkedin=false){const query=[q.company,q.role].filter(Boolean).join(' ');const url=linkedin?'https://www.linkedin.com/search/results/people/?keywords='+encodeURIComponent(query):'https://www.google.com/search?q='+encodeURIComponent('"'+q.company+'" "'+q.role+'"');window.open(url,'_blank','noopener,noreferrer')}
function action(act,el){let x=el?.dataset?.id||'';switch(act){
 case 'toggleMenu':ui.sidebar=!ui.sidebar;render();break;
 case 'openLeo':ui.leo=true;render();break;
 case 'closeLeo':ui.leo=false;render();break;
 case 'leoSuggestion':leoSuggestion(x);break;
 case 'leoPlan':ui.leo=true;leoSuggestion('campaign');break;
 case 'applyLEOSequence':{let c=activeCampaign();if(!c){makeCampaign('pain');ui.leo=false;break}c.steps=buildSteps('pain');c.templateId='pain';ui.leo=false;ui.campaignTab='sequence';ui.selectedStep=null;noteEvent('LEO sequence applied','spark');save();render();toast('LEO sequence applied');break}
 case 'closeModal':ui.modal=null;render();break;
 case 'newProduct':ui.modal={type:'product'};render();break;
 case 'editProduct':ui.modal={type:'product',id:x};render();break;
 case 'selectProduct':ui.selectedProduct=x;state.productId=x;state.filters.productId=x;ui.productTab='detail';save();render();break;
 case 'productTab':ui.productTab=x;render();break;
 case 'addKnowledge':ui.modal={type:'knowledge',id:x};render();break;
 case 'removeKnowledge':state.knowledge=state.knowledge.filter(k=>k.id!==x);save();render();toast('Source removed');break;
 case 'toggleIndustry':{let a=state.filters.industries;a.includes(x)?state.filters.industries=a.filter(i=>i!==x):a.push(x);save();render();break}
 case 'toggleLocation':{let a=state.filters.locations;a.includes(x)?state.filters.locations=a.filter(i=>i!==x):a.push(x);save();render();break}
 case 'selectSize':{let a=state.filters.sizes;if(x==='Any size')a=[];else a.includes(x)?a=a.filter(i=>i!==x):a.push(x);state.filters.sizes=a;save();render();break}
 case 'resetFilters':{state.filters={industries:[],locations:[],sizes:[],signal:'All signals',keyword:'',roles:'',productId:state.filters.productId};save();render();break}
 case 'runDiscovery':applyDiscovery();break;
 case 'saveAccount':{let a=state.discoveries.find(z=>z.id===x),ok=shortlist(a);if(ok){noteEvent(`Account shortlisted: ${a.company}`,'building');save()}render();toast(ok?'Account added to shortlist':'Account is already shortlisted');break}
 case 'saveSelected':{let n=0;ui.selectedAccounts.forEach(y=>{if(shortlist(state.discoveries.find(a=>a.id===y)))n++});ui.selectedAccounts=[];noteEvent(`${n} accounts shortlisted`,'building');save();render();toast(`${n} new accounts added`);break}
 case 'generatePIC':generatePIC();break;
 case 'publicSearch':case 'linkedInSearch':{let q=state.research.find(z=>z.id===x);if(q)publicLink(q,act==='linkedInSearch');break}
 case 'addPIC':ui.modal={type:'pic',id:x||undefined};render();break;
 case 'editContact':ui.modal={type:'pic',contactId:x};render();break;
 case 'importData':ui.modal={type:'import'};render();break;
 case 'confirmImport':confirmImport();break;
 case 'downloadSample':csvDownload([['company','name','role','email','linkedin','industry','website'],['Your Company Name','','Head of Operations','','','Manufacturing','']], 'prospecto_import_template.csv');break;
 case 'exportLeads':csvDownload([['company','name','role','email','linkedin','source','verified'],...state.leads.map(l=>[l.company,l.name,l.role,l.email,l.linkedin,l.source,l.verified])],'prospecto_leads.csv');break;
 case 'leadTab':ui.leadTab=x;render();break;
 case 'newCampaign':ui.modal={type:'newCampaign'};render();break;
 case 'renameCampaign':ui.modal={type:'renameCampaign'};render();break;
 case 'selectTemplates':ui.modal=null;navigate('templates');break;
 case 'useTemplate':makeCampaign(x);break;
 case 'createCampaign':makeCampaign(x);break;
 case 'openCampaign':state.activeCampaign=x;ui.campaignTab='sequence';save();navigate('builder');break;
 case 'campaignTab':ui.campaignTab=x;ui.selectedStep=null;render();break;
 case 'addStep':{let c=activeCampaign();if(!c)return;let type=x||'email';let obj={id:id(),type,title:type==='email'?'New email':type==='wait'?'Wait 3 days':type==='condition'?'If contact replied?':'Manual follow-up',subject:'A note about {{company}}',body:'Hi {{first_name}},\n\nWould you be open to a conversation?\n\nBest,\n{{sender_name}}',days:3,condition:'Has replied?'};c.steps.push(obj);ui.selectedStep=obj.id;save();render();break}
 case 'selectStep':ui.selectedStep=x;render();break;
 case 'saveStep':{let c=activeCampaign(),step=c?.steps.find(s=>s.id===ui.selectedStep);if(!step)return;document.querySelectorAll('[data-step-field]').forEach(field=>{let key=field.dataset.stepField;step[key]=key==='days'?Math.max(1,Number(field.value)||3):field.value});save();render();toast('Step saved');break}
 case 'removeStep':{let c=activeCampaign();c.steps=c.steps.filter(s=>s.id!==x);ui.selectedStep=null;save();render();toast('Step removed');break}
 case 'saveDraft':{let c=activeCampaign();if(!c)return;c.status='Draft';noteEvent(`Campaign draft saved: ${c.name}`,'send');save();render();toast('Campaign saved as draft');break}
 default:break}}
