document.addEventListener('click',e=>{let page=e.target.closest('[data-page]');if(page){e.preventDefault();navigate(page.dataset.page);return}let el=e.target.closest('[data-act]');if(el){e.preventDefault();action(el.dataset.act,el);return}if(e.target.id==='modalShade'){ui.modal=null;render()}if(e.target.id==='leoShade'){ui.leo=false;render()}});
document.addEventListener('change',async e=>{let el=e.target, f=state.filters;
 if(el.id==='targetProduct'){f.productId=el.value;state.productId=el.value;save();return}
 if(el.id==='filterSignal'){f.signal=el.value;save();return}
 if(el.id==='filterKeyword'){f.keyword=el.value.trim();save();return}
 if(el.id==='filterRoles'){f.roles=el.value.trim();save();return}
 if(el.id==='allDiscoveries'){ui.selectedAccounts=el.checked?state.discoveries.map(x=>x.id):[];render();return}
 if(el.dataset.selectAccount){el.checked?ui.selectedAccounts.push(el.dataset.selectAccount):ui.selectedAccounts=ui.selectedAccounts.filter(x=>x!==el.dataset.selectAccount);render();return}
 if(el.dataset.audienceId){let c=activeCampaign();if(!c)return;if(el.checked&&!c.audience.includes(el.dataset.audienceId))c.audience.push(el.dataset.audienceId);else if(!el.checked)c.audience=c.audience.filter(z=>z!==el.dataset.audienceId);save();render();return}
 if(el.dataset.mapCol!==undefined){ui.importMap[Number(el.dataset.mapCol)]=el.value;return}
 if(el.id==='uploadLeadFile'){await readLeadFile(el.files?.[0]);return}
 if(el.id==='leadSearch'){ui.leadSearch=el.value;render();return}
});
