/* Prospecto v9 — customer-facing subscription, account connections and responsible usage.
 * Concept-only frontend. All payment, subscription, OAuth and credit movements are local previews.
 * Production MUST implement entitlements, credit ledger, idempotent billing webhooks, provider usage
 * metering, refunds for failed jobs, tax invoices, tenant isolation and signed OAuth in backend.
 */
const P9_PLANS={growth:{name:'Growth',price:999000,credits:200,seats:3,products:5,leads:1000,campaigns:5},pro:{name:'Pro',price:1999000,credits:600,seats:8,products:20,leads:5000,campaigns:20}};
const P9_PACKS=[{id:'c100',credits:100,price:199000},{id:'c300',credits:300,price:499000,tag:'Popular'},{id:'c1000',credits:1000,price:1499000}];
const P9_CHANNELS=[{id:'gmail',name:'Gmail',desc:'Kirim email campaign dari akun Google Anda.',icon:'mail'},{id:'outlook',name:'Outlook',desc:'Hubungkan email Microsoft 365 untuk campaign.',icon:'mail'},{id:'linkedin',name:'LinkedIn',desc:'Fitur akun atau halaman bisnis sesuai izin resmi.',icon:'users'},{id:'crm',name:'CRM',desc:'Sinkronisasi leads dan aktivitas sales (roadmap).',icon:'database',soon:true}];
const p9month=(raw,n=1)=>{const dt=new Date(raw),day=dt.getDate();const next=new Date(dt.getFullYear(),dt.getMonth()+n,1,12);const days=new Date(next.getFullYear(),next.getMonth()+1,0).getDate();next.setDate(Math.min(day,days));return next.toISOString()};
const p9fmt=(val)=>new Intl.NumberFormat('id-ID').format(val||0);
const p9money=(val)=>'Rp'+p9fmt(val);
const p9date=(x)=>new Date(x).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'});
function p9init(){if(!state.billing){let now=new Date().toISOString();state.billing={plan:'growth',cycleStart:now,cycleEnd:p9month(now),includedUsed:Math.min(state.creditsUsed||0,200),topups:[],ledger:[],status:'preview',pendingPlan:null}}state.billing.topups ||= [];state.billing.ledger ||= [];state.connections ||= {};state.billing.includedUsed ||= 0; state.billing.plan = P9_PLANS[state.billing.plan]?state.billing.plan:'growth';}
p9init();

