campaignsPage=function(){
 const html=v15OriginalCampaigns();const start=html.indexOf('<div class="v11-campaign-hero">'); if(start<0)return html;
 const arr=ui.showMoreTemplates?campaignsTemplates:campaignsTemplates.slice(0,3);
 const hero=`<section class="v15-campaign-hero"><div class="v15-campaign-copy"><span class="v15-section-eyebrow">AI CAMPAIGN STUDIO</span><h2>Dari ide menjadi campaign yang siap dikirim.</h2><p>LEO membantu menyiapkan pesan sesuai produk dan audience. Anda tetap mengatur isi, jadwal, dan persetujuan sebelum campaign dijalankan.</p><div class="v15-hero-actions"><button class="btn btn-primary" data-act="openLeo">${ic('spark',15)} Ask LEO to suggest</button><button class="btn" data-act="useTemplate" data-id="${campaignsTemplates[0]?.id||'intro'}">Start from template ${ic('arrow',14)}</button></div></div><div class="v15-campaign-art"><div class="v15-campaign-timeline"><div class="v15-timeline-title">${ic('layers',15)} 3-step sequence</div><div class="v15-timeline-item"><b>01</b><span>Introduction</span></div><div class="v15-timeline-item"><b>02</b><span>Wait 3 days</span></div><div class="v15-timeline-item"><b>03</b><span>Follow-up</span></div></div><div class="v15-campaign-email"><div class="v15-email-top">${ic('mail',16)} Message preview <span>${ic('spark',13)} LEO</span></div><div class="v15-email-subject">A smarter way to manage operations</div><div class="v15-email-content">Hi &#123;&#123;first_name&#125;&#125;,<br/><br/>Your team may be managing multiple locations. Here’s an idea that could simplify the work...</div><div class="v15-email-bottom"><span>Ready for review</span><b>${ic('send',14)}</b></div></div></div></section>`;
 const gallery=`<div class="v15-template-head"><div><span class="v15-section-eyebrow">START WITH A PLAYBOOK</span><h3>Choose your outreach template</h3><p>Setiap sequence dapat dipersonalisasi menggunakan Product KMS.</p></div><button class="link-btn" data-act="toggleTemplates">${ui.showMoreTemplates?'Show fewer':'View all templates'} ${ic('arrow',14)}</button></div><div class="v15-template-grid">${arr.map((t,i)=>`<article class="v15-template-card"><div class="v15-template-art art-${i%3}">${v15TemplateArt(i)}</div><div class="v15-template-copy"><h4>${esc(t.name)}</h4><p>${esc(t.desc)}</p><div class="v15-template-bottom"><span>${t.steps.length} steps</span><button class="btn btn-sm" data-act="useTemplate" data-id="${t.id}">Use template ${ic('arrow',13)}</button></div></div></article>`).join('')}</div><div class="v15-leo-bar"><span class="v15-leo-icon">${ic('spark',20)}</span><div><b>Not sure where to start?</b><span>LEO can recommend a sequence based on your product and target buyers.</span></div><button class="btn btn-soft" data-act="openLeo">Ask LEO ${ic('arrow',14)}</button></div>`;
 return html.slice(0,start)+hero+gallery;
};
render();

